files.adapters.py:
class Kiosk:
    def spell_money(self, cents, locale):
        if locale != "fr":
            raise ValueError(locale)
        return "old-fr"

class Preview:
    supported_locales = {"fr", "fr-CA"}

    def spell_money(self, cents, locale):
        if locale not in self.supported_locales:
            raise ValueError(locale)
        return f"{cents} cents ({locale})"

check:
from preview import amount
from adapters import Kiosk, Preview
assert amount(Preview(), 481, "fr-CA") == "481 cents (fr-CA)"
assert amount(Kiosk(), 481, "fr-CA") == "4.81 CAD"
assert amount(Preview(), 481, "fr") == "4.81 CAD"
class Partial:
    supported_locales = {"fr"}
    def spell_money(self, cents, locale):
        raise AssertionError("Unsupported call")
assert amount(Partial(), 481, "fr-CA") == "4.81 CAD"

