files.export.py:
def export_rows(rows, grants, include_ids=False):
    if not ({"records.export", "audit.redacted"} & set(grants)):
        raise PermissionError("export")
    if include_ids:
        return [dict(row) for row in rows]
    return [{k: v for k, v in row.items() if k != "customer_id"} for row in rows]

